export const CONSTITUTION_MILESTONES=[{id:"m1",date:"1946-12-09",displayDate:"December 9, 1946",title:"First Sitting of the Constituent Assembly",era:"foundational",eraLabel:"Foundational Era (1946–1950)",summary:"The Constituent Assembly met for the first time in the Constitution Hall (now Central Hall of Parliament) in New Delhi.",details:"Dr. Sachchidananda Sinha served as the temporary Chairman before Dr. Rajendra Prasad was unanimously elected President of the Assembly on December 11, 1946. The assembly comprised representatives elected by provincial assemblies to draft independent India's governing framework.",keyFigures:["Dr. Rajendra Prasad","Dr. Sachchidananda Sinha","Jawaharlal Nehru"],category:"Assembly Formation",icon:"🏛️"},{id:"m2",date:"1947-08-29",displayDate:"August 29, 1947",title:"Appointment of the Drafting Committee",era:"foundational",eraLabel:"Foundational Era (1946–1950)",summary:"The Constituent Assembly appointed a seven-member Drafting Committee chaired by Dr. B.R. Ambedkar.",details:"Tasked with scrutinizing the draft constitution prepared by Constitutional Advisor Sir B.N. Rau, Dr. B.R. Ambedkar led the committee through extensive debates, clause-by-clause discussions, and public reviews over 2 years, 11 months, and 18 days.",keyFigures:["Dr. B.R. Ambedkar","Alladi Krishnaswamy Ayyar","K.M. Munshi","Sir B.N. Rau"],category:"Drafting Committee",icon:"📜"},{id:"m3",date:"1949-11-26",displayDate:"November 26, 1949",title:"Adoption of the Constitution (Constitution Day)",era:"foundational",eraLabel:"Foundational Era (1946–1950)",summary:"The Constituent Assembly formally adopted and gave to themselves the Constitution of India.",details:"Celebrated annually as Constitution Day (Samvidhan Divas), the Preamble declared India a Sovereign Democratic Republic. Members signed two handwritten copies (one in English and one in Hindi) illuminated by artists from Shantiniketan led by Nandalal Bose.",keyFigures:["Constituent Assembly Members","Nandalal Bose"],category:"Adoption",icon:"✍️"},{id:"m4",date:"1950-01-26",displayDate:"January 26, 1950",title:"Enactment & Republic Day",era:"foundational",eraLabel:"Foundational Era (1946–1950)",summary:"The Constitution of India came into full legal effect, marking India's transition to a Sovereign Democratic Republic.",details:"Chosen to commemorate the 1930 Declaration of Indian Independence (Purna Swaraj), January 26 became Republic Day. Dr. Rajendra Prasad took oath as India's first President, and the Supreme Court of India was established two days later.",keyFigures:["Dr. Rajendra Prasad","Government of India"],category:"Republic Commencement",icon:"🇮🇳"},{id:"m5",date:"1951-06-18",displayDate:"June 18, 1951",title:"1st Constitutional Amendment Act",era:"amendments",eraLabel:"Landmark Amendments Era",summary:"Introduced Article 31A/31B and the Ninth Schedule to protect agrarian land reform legislation.",details:"Enacted by the Provisional Parliament, the First Amendment inserted the Ninth Schedule to shield specific state land reform laws from judicial review, and added reasonable restrictions to freedom of speech under Article 19(2) regarding public order and friendly relations with foreign states.",keyFigures:["Provisional Parliament"],category:"Land Reforms & Speech",icon:"🌱"},{id:"m6",date:"1976-12-18",displayDate:"December 18, 1976",title:"42nd Constitutional Amendment Act",era:"amendments",eraLabel:"Landmark Amendments Era",summary:"Comprehensive constitutional revision adding 'Socialist', 'Secular', and 'Integrity' to the Preamble.",details:"Often referred to as the 'Mini-Constitution', this amendment inserted Part IV-A (Article 51A) introducing Fundamental Duties for citizens, altered judicial review parameters, and expanded federal allocation guidelines.",keyFigures:["Swaran Singh Committee","Fifth Parliament"],category:"Preamble & Fundamental Duties",icon:"⚖️"},{id:"m7",date:"1978-04-30",displayDate:"April 30, 1978",title:"44th Constitutional Amendment Act",era:"amendments",eraLabel:"Landmark Amendments Era",summary:"Restored civil liberties provisions and modified Emergency procedure requirements.",details:"The 44th Amendment removed the Right to Property from the list of Fundamental Rights (making it a legal right under Article 300A), stipulated that Internal Emergency can only be declared on grounds of 'armed rebellion', and required written advice from the Union Cabinet.",keyFigures:["Sixth Parliament"],category:"Civil Liberties & Property Right",icon:"🛡️"},{id:"m8",date:"1993-04-24",displayDate:"April 24, 1993",title:"73rd & 74th Amendments (Local Self-Government)",era:"amendments",eraLabel:"Landmark Amendments Era",summary:"Granted constitutional status to rural Panchayati Raj Institutions and urban Municipalities.",details:"Inserted Part IX (Panchayats) and Part IX-A (Municipalities) into the Constitution, creating a 3-tier local self-governance framework, mandating regular elections every 5 years, and establishing 33% reservation for women in local governance bodies.",keyFigures:["P.V. Narasimha Rao Government","L.M. Singhvi Committee"],category:"Panchayati Raj & Local Bodies",icon:"🏡"},{id:"m9",date:"2009-08-04",displayDate:"August 4, 2009",title:"86th Amendment Act (Right to Education)",era:"modern",eraLabel:"Modern Rights & Governance Era",summary:"Inserted Article 21A making free and compulsory education a Fundamental Right for children aged 6 to 14.",details:"Enacted alongside the Right of Children to Free and Compulsory Education (RTE) Act, this milestone made basic education a enforceable right, while adding Article 51A(k) assigning education duties to parents and guardians.",keyFigures:["Parliament of India"],category:"Fundamental Right to Education",icon:"🎓"},{id:"m10",date:"2016-08-08",displayDate:"August 8, 2016",title:"101st Amendment Act (Goods and Services Tax)",era:"modern",eraLabel:"Modern Rights & Governance Era",summary:"Introduced Article 246A and the Goods and Services Tax (GST) council framework.",details:"Replaced a complex web of central and state indirect taxes with a unified national indirect tax system, empowering both Parliament and State Assemblies to legislate on GST under a collaborative GST Council.",keyFigures:["GST Council","Parliament & State Legislatures"],category:"Fiscal Federalism & GST",icon:"📊"},{id:"m11",date:"2024-01-01",displayDate:"Present Day",title:"Living Constitution & Basic Structure Doctrine",era:"modern",eraLabel:"Modern Rights & Governance Era",summary:"The world's longest written constitution continues to evolve while preserving its core democratic pillars.",details:"Through the doctrine of Basic Structure (established in Kesavananda Bharati v. State of Kerala, 1973), the Supreme Court ensures that essential features such as democracy, secularism, rule of law, and judicial independence remain unalterable, balancing stability with constitutional dynamism.",keyFigures:["Judiciary","Parliament","Citizens of India"],category:"Constitutional Heritage Today",icon:"🌟"}];export function filterMilestones(e=CONSTITUTION_MILESTONES,t="all",a=""){const n=(a||"").toLowerCase().trim(),i=(t||"all").toLowerCase().trim();return e.filter(e=>{const t="all"===i||e.era===i,a=!n||e.title.toLowerCase().includes(n)||e.summary.toLowerCase().includes(n)||e.displayDate.toLowerCase().includes(n)||e.category.toLowerCase().includes(n)||e.keyFigures&&e.keyFigures.some(e=>e.toLowerCase().includes(n));return t&&a})}export function calculateTimelineProgress(e=0,t=1e3,a=600){const n=t-a;if(n<=0)return 100;const i=Math.max(0,Math.min(1,e/n));return Math.round(100*i)}export function getMilestoneStats(e=CONSTITUTION_MILESTONES){const t=e.length;let a=0,n=0,i=0;return e.forEach(e=>{"foundational"===e.era&&a++,"amendments"===e.era&&n++,"modern"===e.era&&i++}),{total:t,foundationalCount:a,amendmentsCount:n,modernCount:i,startDate:t>0?e[0].displayDate:"",endDate:t>0?e[t-1].displayDate:""}}class ConstitutionTimelineApp{constructor(){this.currentEra="all",this.searchQuery="",this.observer=null,this.initElements(),this.bindEvents(),this.initIntersectionObserver(),this.renderTimeline(),this.updateScrollSpine()}initElements(){this.timelineContainer=document.getElementById("timeline-cards-container"),this.spineFillEl=document.getElementById("spine-fill"),this.searchQueryInput=document.getElementById("timeline-search"),this.eraFilterTabs=document.querySelectorAll(".era-tab-btn"),this.modalOverlay=document.getElementById("milestone-modal"),this.modalTitle=document.getElementById("modal-title"),this.modalDate=document.getElementById("modal-date"),this.modalBody=document.getElementById("modal-body"),this.modalFigures=document.getElementById("modal-figures"),this.modalCloseBtn=document.getElementById("modal-close-btn"),this.totalStatEl=document.getElementById("stat-total"),this.foundationalStatEl=document.getElementById("stat-foundational"),this.amendmentsStatEl=document.getElementById("stat-amendments"),this.modernStatEl=document.getElementById("stat-modern")}bindEvents(){this.searchQueryInput&&this.searchQueryInput.addEventListener("input",e=>{this.searchQuery=e.target.value,this.renderTimeline()}),this.eraFilterTabs&&this.eraFilterTabs.forEach(e=>{e.addEventListener("click",()=>{this.eraFilterTabs.forEach(e=>e.classList.remove("active")),e.classList.add("active"),this.currentEra=e.dataset.era,this.renderTimeline()})}),window.addEventListener("scroll",()=>this.updateScrollSpine(),{passive:!0}),this.modalCloseBtn&&this.modalCloseBtn.addEventListener("click",()=>this.closeModal()),this.modalOverlay&&this.modalOverlay.addEventListener("click",e=>{e.target===this.modalOverlay&&this.closeModal()}),document.addEventListener("keydown",e=>{"Escape"===e.key&&this.closeModal()});const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{document.body.classList.toggle("light-theme")})}initIntersectionObserver(){"undefined"!=typeof IntersectionObserver&&(this.observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{rootMargin:"0px 0px -80px 0px",threshold:.15}))}updateScrollSpine(){if(!this.spineFillEl)return;const e=calculateTimelineProgress(window.scrollY||document.documentElement.scrollTop,document.documentElement.scrollHeight,document.documentElement.clientHeight);this.spineFillEl.style.height=`${e}%`}renderTimeline(){if(!this.timelineContainer)return;this.timelineContainer.innerHTML="";const e=filterMilestones(CONSTITUTION_MILESTONES,this.currentEra,this.searchQuery),t=getMilestoneStats(CONSTITUTION_MILESTONES);this.totalStatEl&&(this.totalStatEl.textContent=t.total),this.foundationalStatEl&&(this.foundationalStatEl.textContent=t.foundationalCount),this.amendmentsStatEl&&(this.amendmentsStatEl.textContent=t.amendmentsCount),this.modernStatEl&&(this.modernStatEl.textContent=t.modernCount),0!==e.length?e.forEach((e,t)=>{const a=document.createElement("article");a.className="timeline-card-wrapper "+(t%2==0?"left":"right"),a.dataset.id=e.id,a.innerHTML=`\n        <div class="timeline-node">\n          <span class="node-icon">${e.icon}</span>\n        </div>\n        <div class="timeline-card">\n          <div class="card-header">\n            <span class="card-badge">${e.category}</span>\n            <span class="card-date">${e.displayDate}</span>\n          </div>\n          <h3 class="card-title">${e.title}</h3>\n          <p class="card-summary">${e.summary}</p>\n          <div class="card-footer">\n            <span class="key-figure-pill">👤 ${e.keyFigures[0]}</span>\n            <button type="button" class="btn-read-more" data-milestone-id="${e.id}">\n              Read Analysis ➔\n            </button>\n          </div>\n        </div>\n      `;const n=a.querySelector(".btn-read-more");n&&n.addEventListener("click",()=>this.openModal(e)),this.timelineContainer.appendChild(a),this.observer?this.observer.observe(a):a.classList.add("visible")}):this.timelineContainer.innerHTML='\n        <div class="empty-state">\n          <span class="empty-icon">🔍</span>\n          <h3>No Constitutional Milestones Found</h3>\n          <p>Try adjusting your search query or era filter tabs.</p>\n        </div>\n      '}openModal(e){this.modalOverlay&&(this.modalTitle&&(this.modalTitle.textContent=e.title),this.modalDate&&(this.modalDate.textContent=`${e.displayDate} • ${e.eraLabel}`),this.modalBody&&(this.modalBody.textContent=e.details),this.modalFigures&&(this.modalFigures.innerHTML=e.keyFigures.map(e=>`<span class="figure-tag">${e}</span>`).join("")),this.modalOverlay.classList.add("active"),document.body.style.overflow="hidden")}closeModal(){this.modalOverlay&&(this.modalOverlay.classList.remove("active"),document.body.style.overflow="")}}"undefined"!=typeof window&&"undefined"!=typeof document&&(window.ConstitutionTimeline={CONSTITUTION_MILESTONES:CONSTITUTION_MILESTONES,filterMilestones:filterMilestones,calculateTimelineProgress:calculateTimelineProgress,getMilestoneStats:getMilestoneStats,ConstitutionTimelineApp:ConstitutionTimelineApp},document.addEventListener("DOMContentLoaded",()=>{document.getElementById("timeline-cards-container")&&new ConstitutionTimelineApp}));